) AS (
  VALUES 
    (526::BIGINT, 'El peor profesor de Matematica! Ese hombre quedo a todos. Se hace el buena nota en la clase pero te pone 60 solo por no poner un menos en el ejercicio. Es engreido, he visto que tiene un interes por mis compañeras. Habla mucho de las privadas y yo estuve en Fidelitas y ahí encontre mejores profes'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-02T00:00:00+00:00'::TIMESTAMPTZ, '949393586cbf638359f13a296a111db5affedc540be6953bf4e4b6f28675eb9f'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Es una asquerosidad como profesor y como ser humano'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2026-05-23T00:00:00+00:00'::TIMESTAMPTZ, '4aa1fbf93633b8a0f2d4eeba8e19bea52446209be8eb89164fc4ebc8a088aec5'::TEXT, ARRAY[1034]::BIGINT[]),
    (526::BIGINT, 'Explicaciones confusas, desordenado, hace ejemplos como si uno ya supiera del tema. Presentación grandísima que ni se entiende y no va de acuerdo a cronograma de cátedra, la mejor forma de estudiar es con las guías semanales. Lo único bueno es que califica suave entonces es fácil rascar puntos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-14T00:00:00+00:00'::TIMESTAMPTZ, '5064f5abeeb034e425d906ae5c2620a3c8c09dabfc8986fedead09bc4bedca92'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Un vago. Acosador, asqueroso. No sabe nada. No le importa nada. ¿Cómo es posible que él esté aquí? Un mono podría hacer un mejor brete.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas']::TEXT[], '2026-03-27T00:00:00+00:00'::TIMESTAMPTZ, 'c8f38472b55edc1eb8c52ebea7894c7e75b9264732746fa3f057d6c32345ec42'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Si matriculó con él, retire el curso. El peor profe definivamente. Un acosador sexual, irresponsable que se duerme y no explica nada. Solo hablar de comunismo y cosas raras. Los apuntes estan en egipcio y califica fatal.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2026-01-21T00:00:00+00:00'::TIMESTAMPTZ, '25d5ce521418e85a92687a3ebdd562ab611ea501de957a1f5afc311e762e1b13'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'No avisa sobre quices, cuesta entender explicaciones.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '954bfb8c7d48304e280da8639e59aaa4fbcc505165f6844491d7e8d148d01958'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'no les recomiendo llevar con él, explica fatal, es un vago, no responde nunca, es MUY desordenado, nunca responde mensajes, hay veces que hasta se queda dormido en clases, para pasar con él hay que basicamente estudiar por si mismo, de paso habla mal de otros profesores a sus espaldas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'c1a97bb0d1aea3f3af4afcd19764760a315125df7176ed2d764f672ce91c75a2'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Si matriculó con. él, mejor retire el curso, el peor profesor del TEC y UCR. Llegaba tarde, calificaba mal, no explica bien, los apuntes q hace en pizarra eran garabatos, no responde mensajes y tras de todo trata mal a los estudiantes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-11-04T00:00:00+00:00'::TIMESTAMPTZ, '555f0f5bcfdfb8f86cd3c57d96f587e47ee0f4ffd7ba5e559ff0b690273a455c'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Muy mal profe, de los peores que he visto en todo mi estar en el TEC y UCR'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-10-25T00:00:00+00:00'::TIMESTAMPTZ, '0484d63921903e695c7fea1673d00d6bb73f896229e84422289fd6ae5c1aabdf'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'El peor profesor que he tenido en mi vida, llega tarde, no responde mensajes, se inventa excusas y no explica nada. Se metió en una bronca con la directora de cátedra y solo por el cuentazo que se inventó se salió con la suya. Un incompetente que odia su trabajo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'cb1d9b7959409f3092e99fa31d2594c83e537f244d962ffd8f307fdb410c57df'::TEXT, ARRAY[1057]::BIGINT[]),
    (526::BIGINT, 'En serio es el profesor más incompetente que me he topado en el tec. Está completamente desubicado, explica pésimo, nadie le entiende nada.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'b8d0f86e18c39f37103078d4ea9dbde62b27e5f11b8413db3e471713433e440b'::TEXT, ARRAY[1057]::BIGINT[]),
    (526::BIGINT, 'Es un profesor demasiado pero demasiado malo. No se le entiende nada, nos dio materia que no entraba y se atrasó. A la clase le fue pésimo en el examen y lo que medio salvó fueron las clases de otro profesor (cosa que él no sabe). Es muy lamentable que el TEC tenga profesores así.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-02T00:00:00+00:00'::TIMESTAMPTZ, 'e829640d1a8f65bfc83a21f6ecf327305c71b091538ace6debb211f361919249'::TEXT, ARRAY[1057]::BIGINT[]),
    (526::BIGINT, 'El peor profe de matemáticas que me ha dado clases, si matriculó con él, mejor retire el curso'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-03-26T00:00:00+00:00'::TIMESTAMPTZ, '36f0333f03854c25c6f1deac35ed826dd4ce892a3f63808aedd327131cacca6a'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'El peor profesor que he tenido'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-10-30T00:00:00+00:00'::TIMESTAMPTZ, '0b1143560f17341a6fa841ea7ea6c26e5b0b06236b114da42a4a6c824c37a786'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2024-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'b8fce2d260a998f56facb0d1d9ab82465204a97d6a76134a4c0276340262b4f6'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'La verdad no entiendo cómo tiene una nota tan mala , si bien explica por encima a la primera, si usted se lo pide le explica más despacio las veces que sea necesario , si sos repitente con este profe ya pasó, si lo recibe por primera vez nada más es buscar un poco de materia por aparte.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2023-10-15T00:00:00+00:00'::TIMESTAMPTZ, 'b3576f851897a116393297048f7b6ad2be9da6b6608b9c0c7a0ea2d8ea39ab57'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'No es tan malo como dicen las críticas, realmente si ayuda bastante e intenta que el estudiante entienda cuando lo ve perdido. No es el mejor pero es bastante decente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-05-06T00:00:00+00:00'::TIMESTAMPTZ, '7b1fdf1f2cfd06ebf30ebb96a86bd7864ce187c86f3b08507b637e496fe42ae8'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Las clases son muy confusas, pero se le entiende si uno pone suprema atención. Regala puntos en cada examen, literalmente los regala. El curso se pasa solo porque si fuera por el profe, lo regalaría.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2022-11-27T00:00:00+00:00'::TIMESTAMPTZ, '7efca2976cb37e9a9ea7d80c508e28d42a8f416d878aa8cb8b96402a0c09bd53'::TEXT, ARRAY[1057]::BIGINT[]),
    (526::BIGINT, 'El peor profesor que va a ver en su vida, literal, el mae no enseña, sólo se la pasa hablando de sus fetiches con programación y computadoras que a nadie le importa, no acepta reclamos, no ayuda, no muestra notas y cuando lo hace la evaluación es "no me gustó" literal baja puntos por gusto.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Muchos exámenes']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '4bcc21ee26e1a936588e4271608aa6f14ebd5eb1d1339f18f2063a612af45230'::TEXT, ARRAY[103]::BIGINT[]),
    (526::BIGINT, 'El peor profesor que he tenido, es un gran desordenado y bastante repugnante,pierde mucho el tiempo enseñando cosas o hablando de otras cosas sin relación, deja tareas y quizes sin dar aviso y ni él mismo sabe que está haciendo al momento, se enoja si se le pregunta acerca de las fechas.NO MATRICULE'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6adbc282fc641f181f782c5c7db50901ce707878ff80ae78e654051cb07425a9'::TEXT, ARRAY[103]::BIGINT[]),
    (526::BIGINT, 'SALGA CORRIENDO! Digamos que me bastaron 3 clases para decidir retirar el curso. No ayuda, no sabe ni donde está parado, hace quices y tareas sin avisar, divaga y no explica, ni siquiera sabe sobre las evaluaciones. No merece ser profesor del TEC'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-05T00:00:00+00:00'::TIMESTAMPTZ, '4703d695db6e91e6debf2e583e867f9ffb4c4f5fb314c7b11a85e8aae921049d'::TEXT, ARRAY[103]::BIGINT[]),
    (526::BIGINT, 'A él lo que menos le importa es la organización y orden, no se preocupa por las evaluaciones y hace todo muy charral. Es increíblemente desordenado y se enoja cuando se le pregunta algo. El curso se pasa, pero habrá que estudiar de otros lados Y AÚN asistir a clase porque hace quiz y tareassinavisar'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2022-05-28T00:00:00+00:00'::TIMESTAMPTZ, '0d62f0a54222781461df61f97e64946b161c92d187b3d982e8b26dd7f9fecdd7'::TEXT, ARRAY[103]::BIGINT[]),
    (526::BIGINT, 'No recomendado para proba'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-16T00:00:00+00:00'::TIMESTAMPTZ, 'af99e55c898f1390eb2c2c0bab3e5fd1ff1cfdc59edcf439eddf8e5f1603929f'::TEXT, ARRAY[1049]::BIGINT[]),
    (526::BIGINT, 'este profe en serio es increíble. NUNCA había tenido un profesor tan malo. nunca leyó el programa, no dice cuándo van a ser las evaluaciones, se le pregunta algo y no responde absolutamente nada. ni siquiera sube las consignas. háganse un favor y no matriculen con él.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-27T00:00:00+00:00'::TIMESTAMPTZ, '328dfcdc5640a4fb37d16198a73394e0ecb0aa715ddd9e827b59faebf4e35908'::TEXT, ARRAY[103]::BIGINT[]),
    (526::BIGINT, 'El profe se tiró 1 hora entera hablando de política, colores, historia y cualquier anécdota que ni venía al caso, y cuando por fin comenzó a dar materia, no se explicaba bien. Sin duda el peor profesor que he tenido y eso que apenas es semana 2'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2022-02-16T00:00:00+00:00'::TIMESTAMPTZ, '4dd3464360ff19a6084e5a38a8b8ac321a1f85d33b049d1cd7d1b0e7b652ae47'::TEXT, ARRAY[103]::BIGINT[]),
    (526::BIGINT, 'Es muy desordenado, además las explicaciones no eran claras.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '5cea06f80427d3021e6122548e789ee76993e835874071a2d32fa0c5bc749341'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Les recomiendo que investiguen algo más allá de lo que dice el profe porque a veces no se le entiende.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '352d084b4fb21d3d4d4715e878740329d88addd82b20b01b7ff715a73ad0ea85'::TEXT, ARRAY[1049]::BIGINT[]),
    (526::BIGINT, 'No realiza explicaciones claras, se pierde en sus propias ideas.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'b9f59d212c6623f093f1a0dd806a70b2d957077bcc1a6e523d10d6b0e44a81ca'::TEXT, ARRAY[4836]::BIGINT[]),
    (526::BIGINT, 'Malo es poco, dudo que se le pueda llamar profesor. Ni como segunda opción. El dar puntos en exámenes y ser flexible no compensa la mediocridad de las clases que da. No es posible que la escuela tenga a alguien como el.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '12e430276df1cb9d39b83c0a590f267bf1c3922b70dc49d598128dd55b4d4dd4'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (526::BIGINT, 'Pésimo profesor, el peor de mate que he visto hasta el momento. No explica absolutamente nada bien, y no sabe nada de la materia. Se le pregunta y no sabe responder. Aunque se le intente poner atención, no se puede. Habla de una forma muy extraña. No matricule con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'f1f52f1fbdb75e905e12c83bbe96e4be32e727f99a4c05469250fabc862351ec'::TEXT, ARRAY[1057]::BIGINT[]),
    (526::BIGINT, 'Se lo recomiendo si es la segunda vez que lleva el curso, la verdad con él aclaré todas mis dudas de CDI. Y siempre estuvo anuente a responder mis preguntas, si él ve su esfuerzo puede pulsearse cualquier cantidad de puntos.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '360a7c01de749ac420ef303dd1e70c87a0cde047a6d4cefb4a56a5f3580e6ed2'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Si tiene opcion matricule con otro profesor, es pesimo, llega hablar sobre el plan fiscal y como lo quieren despedir de otras universidades por ser mal prof, NUNCA DEBERIA DAR CLASES'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2019-03-13T00:00:00+00:00'::TIMESTAMPTZ, '9641cec7a55a4d0c48b4790f226b8cece82f8adb3bccef7029a1686fed1c289d'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'El peor profesor de la escuela, si tiene oportunidad no matricule con el, no se le entiende y habla medio raro, habian clases completas que no daba nada de materia solo hablas de el mismo o de temas que no tienen relacion.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'edbae165e2bd226dadfcbf31e1d66a154aac22f732fd86603b6d54005c9f30d2'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'Pesimas explicaciones, se sale demasiado del tema,no hace la pestaña de evaluaciones en el TecDigital, hace quices al azar sin avisar y al final la nota de los mismos es lo que él ponga si no va con el cuaderno el día de la entrega de notas. Siempre da puntos en los examenes si va a reclamar'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-28T00:00:00+00:00'::TIMESTAMPTZ, 'be26177567e727dc122fb66a62c2a07ae73b0b2cfc02c246ad527b29659714fd'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'ES UN PESIMO PERO PESIMO PROFESOR, AUN NO ENTIENDO COMO UNA ESCUELA PUEDE TENER ESTE TIPO DE PROFESORES'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-01T00:00:00+00:00'::TIMESTAMPTZ, '97a9435d5631adcdbb0d9304bd6606fc991826d882b31306598503c773efc40e'::TEXT, ARRAY[605]::BIGINT[]),
    (526::BIGINT, 'El curso por si solo es fácil, es posible no ir a clases y pasar, el profe es pura vida para calificar y si el promedio de examenes es bueno, ayuda aun mas. Aunque se ve que de tanto que sabe, se enreda solo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '6ba427d204e7c13103ba4fb396fb0c17bc270bb40482e8d566e4bb6cd5838feb'::TEXT, ARRAY[1049]::BIGINT[]),
    (526::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'b92474d1d5d5d9b624d7df536b6b443a8bad1f11dd8803e847cb10a5a50a1e50'::TEXT, ARRAY[1049]::BIGINT[]),
    (526::BIGINT, 'Profe al cual es mejor no ir a clases, a pesar que es buena gente y califica suave , no se le entiende casi nada, es mejor estudiar con el libro, profe que siempre trata que le vaya bien a los estudiantes, pero igual casi no se le entiende'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-09T00:00:00+00:00'::TIMESTAMPTZ, '4cdcdcb5fd3e794e6161f052b03818339335d44d08878e8ecb78c782a9f77e64'::TEXT, ARRAY[1049]::BIGINT[]),
    (526::BIGINT, 'No explica bien, pero califica suave tanto los exámenes como quices. Apesar de que no se le entiende.siempre está anuente a ayudar. El curso se pasa mejor leyendo y estudiando del libro.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra']::TEXT[], '2016-12-05T00:00:00+00:00'::TIMESTAMPTZ, '5da3df283a4b5a503190989df856c3ec1ff78ad11bd3b2b7be80b9d2f94cd40b'::TEXT, ARRAY[1049]::BIGINT[]),
    (526::BIGINT, 'La mayoria de gente no le entendia, no hace muchos ejemplos a mano. Si ayuda bastante porque deja corregir tareas y es muy flexible con la puntualidad. Hay que apelarle los exámenes porque da puntos.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '12fa2a66ef13d12e83dff2438da17eeabd237126edb8fa4c31de5f2f69495888'::TEXT, ARRAY[103]::BIGINT[]),
    (526::BIGINT, 'Excelente profe.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-02T00:00:00+00:00'::TIMESTAMPTZ, '07af6656275cd91bd80c78ad483cf057986b65607f50d4b68be5315e4196698e'::TEXT, ARRAY[564]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
